  "code": "def rule_form_10k(doc: dict) -> list[dict]:\n    try:\n        import re\n\n        def norm(text: str) -> str:\n            return \" \".join((text or \"\").upper().split())\n\n        def matches(text: str) -> bool:\n            t = norm(text)\n            return bool(\n                re.search(r\"\\bFORM\\s*10\\s*[-]?\\s*K(?:/A)?\\b\", t)\n                or \"ANNUAL REPORT PURSUANT TO SECTION 13 OR 15(D)\" in t\n            )\n\n        def prefix(records, limit):\n            return (records or [])[:limit]\n\n        def collect(records):\n            out = []\n            seen = set()\n            for rec in prefix(records, 120):\n                text = rec.get(\"text\", \"\")\n                if not text or not matches(text):\n                    continue\n                span = {\"text\": text}\n                for key in (\"page_no\", \"paragraph_no\", \"line_no\"):\n                    if key in rec:\n                        span[key] = rec[key]\n                sig = (span.get(\"page_no\"), span.get(\"paragraph_no\"), span.get(\"line_no\"), span[\"text\"])\n                if sig in seen:\n                    continue\n                seen.add(sig)\n                out.append(span)\n                if len(out) >= 2:\n                    break\n            return out\n\n        for bucket in (\"lines\", \"paragraphs\", \"pages\"):\n            spans = collect(doc.get(bucket))\n            if spans:\n                return spans\n\n        return []\n    except Exception:\n        return []\n",
